const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const vesuvius = ee.Geometry.Point([14.426, 40.821]); // Mount Vesuvius coordinates
  const buffer = vesuvius.buffer(1000); // 1km buffer around the summit
  const date = '2022-01-02';

  // 2. Data Acquisition - Landsat 8 Collection 2
  const landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(buffer)
    .filterDate(date, '2022-01-03');

  const collectionSize = landsat8.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Get the image and process cloud mask
  const image = landsat8.first();

  // Extract QA_PIXEL band and create cloud mask
  const qa = image.select('QA_PIXEL');

  // Bits for cloud detection in QA_PIXEL (Collection 2)
  const cloudBit = 1 << 5;      // Bit 5: Cloud
  const cloudShadowBit = 1 << 3; // Bit 3: Cloud shadow
  const snowBit = 1 << 4;       // Bit 4: Snow

  // Create cloud mask (1 = clear, 0 = cloud/cloud shadow/snow)
  const cloudMask = qa.bitwiseAnd(cloudBit).eq(0)
    .and(qa.bitwiseAnd(cloudShadowBit).eq(0))
    .and(qa.bitwiseAnd(snowBit).eq(0));

  // 4. Calculate cloud statistics over the buffer area
  const stats = cloudMask.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: buffer,
    scale: 30,
    maxPixels: 1e9
  });

  const clearPercentage = stats.get('QA_PIXEL_mean').getInfo();
  const totalPixels = stats.get('QA_PIXEL_count').getInfo();

  console.log(`Clear pixel percentage: ${(clearPercentage * 100).toFixed(1)}%`);
  console.log(`Total pixels analyzed: ${totalPixels}`);

  // 5. Validation & Final Answer
  if (totalPixels === 0) {
    console.log("<answer>C2</answer>");
  } else if (clearPercentage === null || clearPercentage === undefined || clearPercentage < 0 || clearPercentage > 1) {
    console.log("<answer>C3</answer>");
  } else if (clearPercentage > 0.1) { // If >10% clear, consider visible
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
